def solve(g):
    H=len(g); W=len(g[0])
    bg=g[0][0]
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    # separator color: color forming full row/col != bg
    sep=None
    for i in range(H):
        if len(set(g[i]))==1 and g[i][0]!=bg: sep=g[i][0]; break
    if sep is None:
        for j in range(W):
            if len({g[i][j] for i in range(H)})==1 and g[0][j]!=bg: sep=g[0][j]; break
    srow=[i for i in range(H) if all(v==sep for v in g[i])]
    scol=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    O=[[bg]*(W-1) for _ in range(H-1)]
    cells=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] not in (bg,sep)]
    for i,j,c in cells:
        rr=i if i<srow[0] else i-1
        cc=j if j<scol[0] else j-1
        h,w=H-1,W-1
        for r in (rr,h-1-rr):
            for c2 in (cc,w-1-cc):
                O[r][c2]=c
    return O
